.SECONDEXPANSION:
LIST = first
all: $$(LIST)
	@printf 'all\n'
LIST = second
first:
	@printf 'first\n'
second:
	@printf 'second\n'

all: old new
	@printf '%s' '$?' > first
	@printf updated > all
	@printf '<%s>|<%s>\n' '$?' '$+'

.PHONY: dep
dep:
	@printf ran > marker
all: dep
	@printf '<%s>' '$?'

VALUE := $(if yes,ok,$(shell printf wrong > side-effect))
all:
	@printf '<%s>' '$(VALUE)'
